    <!-- ===== CARRINHO MODAL ===== -->
    <div class="modal" id="cartModal">
        <div class="modal-content cart-modal-content">
            <div class="modal-header">
                <h2>Seu Carrinho</h2>
                <button class="close-btn" onclick="closeCartModal()">✕</button>
            </div>
            
            <div id="cartItems" class="cart-items">
                <!-- Itens do carrinho serão inseridos aqui -->
            </div>

            <div id="cartSummary" class="cart-summary">
                <div class="summary-row">
                    <span>Subtotal</span>
                    <span id="subtotal">R$ 0,00</span>
                </div>
                <div class="summary-row">
                    <span>Frete</span>
                    <span id="shipping">R$ 0,00</span>
                </div>
                <div class="summary-row">
                    <span>Desconto</span>
                    <span id="discount">R$ 0,00</span>
                </div>
                <div class="summary-total">
                    <div class="summary-row">
                        <span>Total</span>
                        <span id="total">R$ 0,00</span>
                    </div>
                </div>
            </div>

            <div id="cartActions" class="form-actions">
                <button class="btn-primary" onclick="checkout()">Finalizar Compra</button>
                <button class="btn-secondary" onclick="closeCartModal()">Continuar Comprando</button>
            </div>
        </div>
    </div>

    <!-- ===== JAVASCRIPT ===== -->
    <script>
        // Imagens em Base64 para garantir que funcionem sem pasta externa
        const imgAsics = '';
        const imgMikasa = '';
        const imgBrasil = '';
        const imgManguito = '';
        const imgJoelheira = '';
        const imgFutebol = '';

        // ===== DADOS DOS PRODUTOS =====
        const products = [
            {
                id: 1,
                name: 'Tênis Asics Gel-Nimbus',
                category: 'Calçados',
                price: 949.90,
                oldPrice: 1199.90,
                description: 'O máximo em amortecimento e conforto para sua corrida.',
                rating: 5,
                badge: 'Destaque',
                image: 'data:image/webp;base64,'
            },
            {
                id: 2,
                name: 'Bola Mikasa V200W',
                category: 'Equipamentos',
                price: 549.90,
                oldPrice: 699.90,
                description: 'Bola oficial de vôlei aprovada pela FIVB.',
                rating: 5,
                badge: 'Profissional',
                image: 'data:image/jpeg;base64,'
            },
            {
                id: 3,
                name: 'Camiseta Brasil Amarela',
                category: 'Roupas',
                price: 349.90,
                oldPrice: 399.90,
                description: 'Camisa oficial da seleção brasileira, tecido tecnológico.',
                rating: 5,
                badge: 'Oficial',
                image: 'data:image/jpeg;base64,'
            },
            {
                id: 4,
                name: 'Manguito N1 Sport',
                category: 'Acessórios',
                price: 89.90,
                oldPrice: 119.90,
                description: 'Manguito de compressão para vôlei e esportes de alta performance.',
                rating: 4,
                badge: 'Novo',
                image: 'data:image/webp;base64,'
            },
            {
                id: 5,
                name: 'Joelheira N1 Sport',
                category: 'Acessórios',
                price: 129.90,
                oldPrice: 159.90,
                description: 'Proteção e estabilidade para seus joelhos durante o jogo.',
                rating: 5,
                badge: 'Vendido+',
                image: 'data:image/webp;base64,'
            },
            {
                id: 6,
                name: 'Bola de Futebol',
                category: 'Bolas',
                price: 159.90,
                oldPrice: 199.90,
                description: 'Bola resistente para futebol de campo ou society.',
                rating: 4,
                badge: 'Promo',
                image: 'data:image/jpeg;base64,'
            }
        ];

        // ===== CARRINHO DE COMPRAS =====
        let cart = [];

        // ===== RENDERIZAR PRODUTOS =====
        function renderProducts() {
            const productsGrid = document.getElementById('productsGrid');
            productsGrid.innerHTML = products.map(product => `
                <div class="product-card">
                    <div class="product-image">
                        <img src="${product.image}" alt="${product.name}">
                        ${product.badge ? `<span class="product-badge">${product.badge}</span>` : ''}
                    </div>
                    <div class="product-info">
                        <div class="product-category">${product.category}</div>
                        <h3 class="product-name">${product.name}</h3>
                        <p class="product-description">${product.description}</p>
                        <div class="product-rating">
                            ${Array(product.rating).fill('⭐').join('')}
                        </div>
                        <div class="product-footer">
                            <div>
                                ${product.oldPrice ? `<span class="product-price-old">R$ ${product.oldPrice.toFixed(2).replace('.', ',')}</span>` : ''}
                                <div class="product-price">R$ ${product.price.toFixed(2).replace('.', ',')}</div>
                            </div>
                            <button class="add-to-cart-btn" onclick="addToCart(${product.id})">Adicionar</button>
                        </div>
                    </div>
                </div>
            `).join('');
        }

        // ===== ADICIONAR AO CARRINHO =====
        function addToCart(productId) {
            const product = products.find(p => p.id === productId);
            const existingItem = cart.find(item => item.id === productId);

            if (existingItem) {
                existingItem.quantity++;
            } else {
                cart.push({
                    ...product,
                    quantity: 1
                });
            }

            updateCartCount();
            showNotification(`${product.name} adicionado ao carrinho!`);
        }

        // ===== REMOVER DO CARRINHO =====
        function removeFromCart(productId) {
            cart = cart.filter(item => item.id !== productId);
            updateCartCount();
            renderCart();
        }

        // ===== ATUALIZAR QUANTIDADE =====
        function updateQuantity(productId, quantity) {
            const item = cart.find(item => item.id === productId);
            if (item) {
                item.quantity = Math.max(1, quantity);
                renderCart();
            }
        }

        // ===== ATUALIZAR CONTAGEM DO CARRINHO =====
        function updateCartCount() {
            const count = cart.reduce((total, item) => total + item.quantity, 0);
            document.getElementById('cartCount').textContent = count;
        }

        // ===== RENDERIZAR CARRINHO =====
        function renderCart() {
            const cartItems = document.getElementById('cartItems');
            const cartSummary = document.getElementById('cartSummary');
            const cartActions = document.getElementById('cartActions');

            if (cart.length === 0) {
                cartItems.innerHTML = `
                    <div class="empty-cart">
                        <div class="empty-cart-icon">🛒</div>
                        <p>Seu carrinho está vazio</p>
                        <p style="font-size: 0.9rem; margin-top: 0.5rem;">Adicione produtos para começar suas compras</p>
                    </div>
                `;
                cartSummary.style.display = 'none';
                cartActions.style.display = 'none';
            } else {
                cartItems.innerHTML = cart.map(item => `
                    <div class="cart-item">
                        <div class="cart-item-info">
                            <div class="cart-item-name">${item.name}</div>
                            <div class="cart-item-price">R$ ${item.price.toFixed(2).replace('.', ',')}</div>
                        </div>
                        <div class="cart-item-quantity">
                            <button onclick="updateQuantity(${item.id}, ${item.quantity - 1})">−</button>
                            <span>${item.quantity}</span>
                            <button onclick="updateQuantity(${item.id}, ${item.quantity + 1})">+</button>
                        </div>
                        <button class="remove-item-btn" onclick="removeFromCart(${item.id})">✕</button>
                    </div>
                `).join('');

                // Calcular totais
                const subtotal = cart.reduce((total, item) => total + (item.price * item.quantity), 0);
                const shipping = subtotal >= 100 ? 0 : 15;
                const discount = subtotal >= 500 ? subtotal * 0.1 : 0;
                const total = subtotal + shipping - discount;

                document.getElementById('subtotal').textContent = `R$ ${subtotal.toFixed(2).replace('.', ',')}`;
                document.getElementById('shipping').textContent = shipping === 0 ? 'Grátis' : `R$ ${shipping.toFixed(2).replace('.', ',')}`;
                document.getElementById('discount').textContent = discount > 0 ? `-R$ ${discount.toFixed(2).replace('.', ',')}` : 'R$ 0,00';
                document.getElementById('total').textContent = `R$ ${total.toFixed(2).replace('.', ',')}`;

                cartSummary.style.display = 'block';
                cartActions.style.display = 'flex';
            }
        }

        // ===== MODAIS =====
        function openLoginModal() {
            document.getElementById('loginModal').classList.add('active');
            document.body.style.overflow = 'hidden';
        }

        function closeLoginModal() {
            document.getElementById('loginModal').classList.remove('active');
            document.body.style.overflow = 'auto';
            resetForms();
        }

        function openCartModal() {
            document.getElementById('cartModal').classList.add('active');
            document.body.style.overflow = 'hidden';
            renderCart();
        }

        function closeCartModal() {
            document.getElementById('cartModal').classList.remove('active');
            document.body.style.overflow = 'auto';
        }

        // ===== ALTERNAR ENTRE LOGIN E CADASTRO =====
        function toggleForms() {
            const loginForm = document.getElementById('loginForm');
            const signupForm = document.getElementById('signupForm');
            const modalTitle = document.getElementById('modalTitle');

            loginForm.classList.toggle('hidden');
            signupForm.classList.toggle('hidden');
            modalTitle.textContent = loginForm.classList.contains('hidden') ? 'Criar Conta' : 'Fazer Login';
        }

        // ===== RESETAR FORMULÁRIOS =====
        function resetForms() {
            document.getElementById('loginForm').reset();
            document.getElementById('signupForm').reset();
            document.getElementById('loginForm').classList.remove('hidden');
            document.getElementById('signupForm').classList.add('hidden');
            document.getElementById('modalTitle').textContent = 'Fazer Login';
        }

        // ===== ENVIAR FORMULÁRIOS =====
        document.getElementById('loginForm').addEventListener('submit', function(e) {
            e.preventDefault();
            const email = document.getElementById('loginEmail').value;
            showNotification(`Bem-vindo de volta, ${email}!`);
            closeLoginModal();
        });

        document.getElementById('signupForm').addEventListener('submit', function(e) {
            e.preventDefault();
            const name = document.getElementById('signupName').value;
            showNotification(`Conta criada com sucesso, ${name}! Bem-vindo à Beka Esporte!`);
            closeLoginModal();
        });

        // ===== CHECKOUT =====
        function checkout() {
            if (cart.length === 0) {
                showNotification('Seu carrinho está vazio!');
                return;
            }
            showNotification('Redirecionando para pagamento...');
            setTimeout(() => {
                cart = [];
                updateCartCount();
                closeCartModal();
                showNotification('Compra realizada com sucesso! Obrigado!');
            }, 1500);
        }

        // ===== NOTIFICAÇÕES =====
        function showNotification(message) {
            const notification = document.createElement('div');
            notification.style.cssText = `
                position: fixed;
                top: 20px;
                right: 20px;
                background-color: var(--secondary-color);
                color: white;
                padding: 1rem 1.5rem;
                border-radius: 8px;
                box-shadow: var(--shadow-lg);
                z-index: 3000;
                animation: slideUp 0.3s ease;
                max-width: 300px;
            `;
            notification.textContent = message;
            document.body.appendChild(notification);

            setTimeout(() => {
                notification.style.animation = 'fadeIn 0.3s ease reverse';
                setTimeout(() => notification.remove(), 300);
            }, 3000);
        }

        // ===== MENU HAMBURGER =====
        document.getElementById('hamburger').addEventListener('click', function() {
            const navMenu = document.querySelector('.nav-menu');
            navMenu.classList.toggle('active');
            this.classList.toggle('active');
        });

        // Fechar menu ao clicar em um link
        document.querySelectorAll('.nav-menu a').forEach(link => {
            link.addEventListener('click', function() {
                document.querySelector('.nav-menu').classList.remove('active');
                document.getElementById('hamburger').classList.remove('active');
            });
        });

        // Fechar modal ao clicar fora
        window.addEventListener('click', function(event) {
            const loginModal = document.getElementById('loginModal');
            const cartModal = document.getElementById('cartModal');

            if (event.target === loginModal) {
                closeLoginModal();
            }
            if (event.target === cartModal) {
                closeCartModal();
            }
        });

        // ===== INICIALIZAR =====
        document.addEventListener('DOMContentLoaded', () => {
            renderProducts();
        });
    </script>
</body>
